/* prog38_continued_fraction.c
 * Reimplementation of the original obfuscated binary.
 * It reads two integers from the command line, computes the continued‑fraction
 * expansion of the rational number a/b and prints it in the form
 *   [q0; q1, q2, ...]
 * handling all error cases that the original program reported.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_ABS_VALUE 100000

static void print_error(const char *msg)
{
    puts(msg);
}

/* Parse a single argument with strict error checking.
 * Returns 0 on success, non‑zero on failure. */
static int parse_long(const char *s, long *out)
{
    char *endptr = NULL;
    errno = 0;
    long val = strtol(s, &endptr, 10);

    if (endptr == s)            /* no digits */
        return -1;
    if (*endptr != '\0')       /* extra characters */
        return -1;
    if (errno == ERANGE)        /* overflow/underflow */
        return -1;
    *out = val;
    return 0;
}

/* Compute the continued‑fraction terms of a / b.
 * The terms are stored in the supplied array; the function returns the number
 * of terms.  Both a and b may be negative – the algorithm follows C's integer
 * division semantics (truncates toward zero). */
static size_t continued_fraction(long a, long b, long *terms, size_t max_terms)
{
    size_t cnt = 0;
    while (b != 0 && cnt < max_terms) {
        long q = a / b;
        long r = a % b;
        terms[cnt++] = q;
        a = b;
        b = r;
    }
    return cnt;
}

int main(int argc, char *argv[])
{
    /* 1. Argument count */
    if (argc < 3) {
        print_error("NO_INPUT");
        return 0;
    }

    /* 2. Parse arguments */
    long num, den;
    if (parse_long(argv[1], &num) != 0 || parse_long(argv[2], &den) != 0) {
        print_error("BAD_INPUT");
        return 0;
    }

    /* 3. Range check */
    if (num > MAX_ABS_VALUE || num < -MAX_ABS_VALUE ||
        den > MAX_ABS_VALUE || den < -MAX_ABS_VALUE) {
        print_error("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Denominator zero */
    if (den == 0) {
        print_error("ERROR");
        return 0;
    }

    /* 5. Compute continued fraction */
    long terms[201];
    size_t n = continued_fraction(num, den, terms, 201);

    /* 6. Output */
    putchar('[');
    if (n > 0) {
        printf("%ld", terms[0]);
        if (n > 1) {
            printf("; ");
            for (size_t i = 1; i < n; ++i) {
                printf("%ld", terms[i]);
                if (i + 1 < n)
                    printf(", ");
            }
        }
    }
    printf("]\n");
    return 0;
}
